      {
        "id": "aff_4",
        "label": null,
        "text": "Department of Physics and Materials Science, University of Luxembourg, 162A Avenue de la Faïencerie, L-1511 Luxembourg, Grand Duchy of Luxembourg"
      }
    ],
    "authors": [
      {
        "id": "author_1",
        "full_name": "Konstantin L. Metlov",
        "orcid": null,
        "email": "metlov@fti.dn.ua",
        "is_corresponding": true,
        "affiliation_refs": [
          "aff_1",
          "aff_2"
        ]
