      {
        "id": "author_2",
        "full_name": "Kiyonori Suzuki",
        "orcid": null,
        "email": null,
        "is_corresponding": false,
        "affiliation_refs": [
          "aff_3"
        ]
      },
      {
        "id": "author_3",
        "full_name": "Dirk Honecker",
        "orcid": null,
        "email": null,
        "is_corresponding": false,
        "affiliation_refs": [
          "aff_4"
